import {useState} from "react";
import {useLoaderData, useNavigate} from "react-router-dom";
import cookie from "react-cookies";
import Headers from "../utils/HeadersNew";

interface User {
  user_id: string;
  name: string;
  email?: string;
  nickname: string;
  register_time: string;
  recent_login_time: string;
  role: string;
  profile_image: string;
  phone: string;
}

export async function myInfoLoader() {
  const accessToken = cookie.load("accessToken") ?? "";
  const memberId = cookie.load("memberId") ?? "";
  const res = await fetch(
    `/api/user/info?member_id=${memberId}`,
    {
      method: "GET",
      headers: {
        "Content-Type": "application/json",
        access_token: accessToken,
      },
    }
  );
  const data = await res.json();
  return {user: data.result_data?.[0] || null};
}

export default function Home() {
  const {user} = useLoaderData() as {user: User | null};
  const [nickName, setNickName] = useState(user?.nickname || "");
  const navigate = useNavigate();

  const UserInfoField = ({
    label,
    value,
    disabled = true,
  }: {
    label: string;
    value: string;
    disabled?: boolean;
  }) => (
    <div>
      <label className="block text-sm font-medium text-gray-500 dark:text-gray-400 mb-1">
        {label}
      </label>
      <input
        value={value || ""}
        disabled={disabled}
        className="block w-full rounded-lg border border-gray-200 dark:border-gray-600 py-2 px-3
                   text-sm text-gray-700 dark:text-gray-300 bg-gray-50 dark:bg-gray-700 shadow-sm
                   disabled:opacity-70"
      />
    </div>
  );

  const onChangeNickName = (e: React.ChangeEvent<HTMLInputElement>) => {
    setNickName(e.target.value);
  };

  const onChangeNickNameToServer = async () => {
    try {
      const data = {
        member_id: cookie.load("memberId"),
        user_id: cookie.load("userId"),
        nickname: nickName,
      };
      const res = await fetch(`/api/update/nickname`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          access_token: cookie.load("accessToken"),
        },
        body: JSON.stringify(data),
      });
      const result = await res.json();

      if (result.error_code === 0) {
        alert("NickName Updated");
        window.location.reload();
      } else if (result.error_code === 106) {
        alert("닉네임은 하루에 한번만 업데이트할 수 있습니다.");
      }
    } catch (err) {
      console.error("update nickname error:", err);
    }
  };

  const goSignIn = () => navigate("/login");
  const goMyPage = () => navigate("/mypage");

  return (
    <div className="min-h-screen bg-gray-100 dark:bg-gray-900 transition-colors duration-200">
      <Headers />
      <main className="grid grid-cols-1 md:grid-cols-12 gap-6 px-4 sm:px-6 py-4 sm:py-6">
        <section className="col-span-1 md:col-span-8 space-y-4">
          {user && (
            <div className="bg-white dark:bg-gray-800 rounded-xl shadow p-6 space-y-4">
              <div className="flex items-center space-x-4 pb-4 border-b border-gray-100 dark:border-gray-700">
                <img
                  src={user.profile_image}
                  alt="profile"
                  className="w-14 h-14 rounded-full border-2 border-orange-200"
                />
                <div>
                  <h2 className="text-lg font-semibold text-gray-800 dark:text-gray-100">
                    {user.nickname || user.name}
                  </h2>
                  <p className="text-sm text-gray-500 dark:text-gray-400">
                    {user.email}
                  </p>
                </div>
              </div>

              <UserInfoField label="ID" value={user.user_id} />
              <UserInfoField label="Email" value={user.email || "-"} />

              <div>
                <label className="block text-sm font-medium text-gray-500 dark:text-gray-400 mb-1">
                  NickName
                </label>
                <div className="flex gap-2">
                  <input
                    id="nickName"
                    value={nickName}
                    onChange={onChangeNickName}
                    className="flex-1 rounded-lg border border-gray-200 dark:border-gray-600 py-2 px-3
                    text-sm text-gray-700 dark:text-gray-300 bg-gray-50 dark:bg-gray-700 shadow-sm
                    focus:outline-none focus:border-orange-300 focus:ring-1 focus:ring-orange-200"
                  />
                  <button
                    onClick={onChangeNickNameToServer}
                    className="px-4 bg-gradient-to-r from-rose-300 to-orange-300
                    hover:from-rose-400 hover:to-orange-400
                    text-white text-sm font-semibold rounded-lg py-2 shadow-sm
                    transition-all duration-300"
                  >
                    Change
                  </button>
                </div>
              </div>

              <UserInfoField
                label="Phone Number"
                value={user.phone || "Not Registered"}
              />
              <UserInfoField label="Role" value={user.role} />

              <div className="grid grid-cols-2 gap-3 pt-2">
                <button
                  onClick={goMyPage}
                  className="w-full bg-gradient-to-r from-rose-300 to-orange-300
                  hover:from-rose-400 hover:to-orange-400
                  text-white font-semibold rounded-xl py-2 shadow-sm
                  transition-all duration-300"
                >
                  My Page
                </button>
                <button
                  onClick={goSignIn}
                  className="w-full bg-gradient-to-r from-rose-300 to-orange-300
                  hover:from-rose-400 hover:to-orange-400
                  text-white font-semibold rounded-xl py-2 shadow-sm
                  transition-all duration-300"
                >
                  Sign In
                </button>
              </div>
            </div>
          )}
        </section>

        <aside className="col-span-1 md:col-span-4">
          <div className="bg-white dark:bg-gray-800 rounded-xl shadow p-4">
            <h2 className="text-lg font-semibold mb-3 text-gray-800 dark:text-gray-100">
              계정 정보
            </h2>
            <ul className="space-y-3 text-sm text-gray-600 dark:text-gray-300">
              <li className="flex justify-between">
                <span className="text-gray-500 dark:text-gray-400">역할</span>
                <span className="font-medium">{user?.role ?? "-"}</span>
              </li>
              <li className="flex justify-between">
                <span className="text-gray-500 dark:text-gray-400">가입일</span>
                <span className="font-medium">
                  {user
                    ? new Date(user.register_time + "Z").toLocaleDateString(
                        "ko-KR",
                        {
                          timeZone: "Asia/Seoul",
                        }
                      )
                    : "-"}
                </span>
              </li>
              <li className="flex justify-between">
                <span className="text-gray-500 dark:text-gray-400">닉네임</span>
                <span className="font-medium">{user?.nickname ?? "-"}</span>
              </li>
            </ul>
          </div>
        </aside>
      </main>
    </div>
  );
}
